pub enum Y {
    /// A length.
    Length(Length),
    /// A percentage.
    Percentage(Percentage),
}

impl fmt::Display for Y {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Length(v) => v.fmt(f),
            Self::Percentage(v) => v.fmt(f),
        }
    }
}

impl From<Length> for Y {
    fn from(v: Length) -> Self {
        Self::Length(v)
    }
}

impl From<Percentage> for Y {
    fn from(v: Percentage) -> Self {
        Self::Percentage(v)
    }
}

/// A value of [`z-index`](https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/z-index).
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub enum ZIndex {
    /// `auto`.
    Auto,
    /// An integer.
    Integer(i32),
}

impl fmt::Display for ZIndex {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Auto => f.write_str("auto"),
            Self::Integer(v) => v.fmt(f),
        }
    }
}

impl From<i32> for ZIndex {
    fn from(v: i32) -> Self {
        Self::Integer(v)
    }
}

/// A value of [`zoom`](https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/zoom).
#[derive(Debug, Clone, PartialEq)]
#[non_exhaustive]
pub enum Zoom {
    /// `normal`.
    Normal,
    /// `reset`.
    Reset,
    /// A percentage.
    Percentage(Percentage),
    /// A number.
    Number(f64),
    /// Any other value, passed through unchecked.
    Raw(Raw),
}

impl fmt::Display for Zoom {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Normal => f.write_str("normal"),
            Self::Reset => f.write_str("reset"),
            Self::Percentage(v) => v.fmt(f),
            Self::Number(v) => crate::value::number(*v).fmt(f),
            Self::Raw(v) => v.fmt(f),
        }
    }
}

impl From<Percentage> for Zoom {
    fn from(v: Percentage) -> Self {
        Self::Percentage(v)
    }
}

impl From<f64> for Zoom {
    fn from(v: f64) -> Self {
        Self::Number(v)
    }
}

impl From<i32> for Zoom {
    fn from(v: i32) -> Self {
        Self::Number(f64::from(v))
    }
}

impl From<Raw> for Zoom {
    fn from(v: Raw) -> Self {
        Self::Raw(v)
    }
}

